import { useEffect, useState } from 'react';
import API from '../services/api';

import Sidebar from '../components/Sidebar';

function Devices() {

    const [devices, setDevices] = useState([]);
    const [loading, setLoading] = useState(true);

    // Add device form
    const [showAddForm, setShowAddForm] = useState(false);
    const [newName, setNewName] = useState('');
    const [newLimit, setNewLimit] = useState(1000);
    const [newAutoOff, setNewAutoOff] = useState('');

    // Newly created device, shown once in a "copy this into your sensor" panel
    const [justCreated, setJustCreated] = useState(null);

    // Inline edit state: deviceId -> { name, powerLimit, autoOffMinutes }
    const [editing, setEditing] = useState(null);
    const [editValues, setEditValues] = useState({});

    const [revealedKeys, setRevealedKeys] = useState({});
    const [busyId, setBusyId] = useState(null);

    const apiBase = process.env.REACT_APP_API_URL || 'http://localhost:5000';

    const fetchDevices = async () => {
        try {
            const res = await API.get('/device');
            setDevices(res.data);
        } catch (error) {
            console.log(error);
        } finally {
            setLoading(false);
        }
    };

    useEffect(() => {
        fetchDevices();
    }, []);

    const handleAddDevice = async () => {
        if (!newName.trim()) {
            alert('Please enter a device name');
            return;
        }
        try {
            const res = await API.post('/device', {
                name: newName.trim(),
                powerLimit: Number(newLimit) || 1000,
                autoOffMinutes: newAutoOff ? Number(newAutoOff) : null
            });
            setDevices([res.data, ...devices]);
            setJustCreated(res.data);
            setNewName('');
            setNewLimit(1000);
            setNewAutoOff('');
            setShowAddForm(false);
        } catch (error) {
            alert(error.response?.data?.message || 'Could not add device');
        }
    };

    const startEdit = (device) => {
        setEditing(device._id);
        setEditValues({
            name: device.name,
            powerLimit: device.powerLimit,
            autoOffMinutes: device.autoOffMinutes || ''
        });
    };

    const saveEdit = async (id) => {
        try {
            const res = await API.put(`/device/${id}`, {
                name: editValues.name,
                powerLimit: Number(editValues.powerLimit),
                autoOffMinutes: editValues.autoOffMinutes ? Number(editValues.autoOffMinutes) : null
            });
            setDevices(devices.map(d => d._id === id ? res.data : d));
            setEditing(null);
        } catch (error) {
            alert(error.response?.data?.message || 'Could not update device');
        }
    };

    const toggleDevice = async (device) => {
        setBusyId(device._id);
        try {
            const action = device.status === 'ON' ? 'turn-off' : 'turn-on';
            const res = await API.post(`/device/${device._id}/${action}`);
            setDevices(devices.map(d => d._id === device._id ? res.data.device : d));
        } catch (error) {
            alert(error.response?.data?.message || 'Could not update device status');
        } finally {
            setBusyId(null);
        }
    };

    const deleteDevice = async (device) => {
        if (!window.confirm(`Delete "${device.name}"? This also removes its usage history.`)) return;
        try {
            await API.delete(`/device/${device._id}`);
            setDevices(devices.filter(d => d._id !== device._id));
        } catch (error) {
            alert(error.response?.data?.message || 'Could not delete device');
        }
    };

    const regenerateKey = async (device) => {
        if (!window.confirm('Regenerate API key? The old key will stop working immediately - update your sensor firmware with the new one.')) return;
        try {
            const res = await API.post(`/device/${device._id}/regenerate-key`);
            setDevices(devices.map(d => d._id === device._id ? { ...d, apiKey: res.data.apiKey } : d));
            setRevealedKeys({ ...revealedKeys, [device._id]: true });
        } catch (error) {
            alert(error.response?.data?.message || 'Could not regenerate key');
        }
    };

    const copyToClipboard = (text) => {
        navigator.clipboard.writeText(text);
    };

    return (
        <div className="flex min-h-screen bg-surface text-on-surface font-inter">

            {/* SIDEBAR */}
            <Sidebar />

            {/* MAIN */}
            <div className="pl-72 flex-1">

                {/* TOP HEADER BAR */}
                <header className="fixed top-0 left-72 right-0 h-16 bg-surface-dim/70 backdrop-blur-2xl z-40 flex items-center justify-between px-6 border-b border-glass-stroke">
                    <div />
                    <div className="flex items-center gap-3 pl-4">
                        <div className="w-8 h-8 rounded-full bg-gradient-to-br from-electric-blue to-vibrant-violet flex items-center justify-center">
                            <span className="material-symbols-outlined text-white text-[18px]">person</span>
                        </div>
                    </div>
                </header>

                <main className="pt-16 min-h-screen">
                    <div className="p-6">

                        <div className="flex justify-between items-center mb-8">
                            <div>
                                <h1 className="text-headline-lg text-on-surface">Devices</h1>
                                <p className="text-body-md text-on-surface-variant mt-1">
                                    Add sensors, set power limits, and control devices.
                                </p>
                            </div>
                            <button
                                onClick={() => setShowAddForm(!showAddForm)}
                                className="btn-primary flex items-center gap-2"
                            >
                                <span className="material-symbols-outlined text-[18px]">add</span>
                                Add Device
                            </button>
                        </div>

                        {/* ADD DEVICE FORM */}
                        {showAddForm && (
                            <div className="glass-card p-card-padding mb-8">
                                <h2 className="text-title-md font-inter text-on-surface mb-6 flex items-center gap-2">
                                    <span className="material-symbols-outlined text-electric-blue">add_circle</span>
                                    New Device
                                </h2>
                                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                                    <div>
                                        <label className="text-label-caps text-on-surface-variant uppercase tracking-widest mb-2 block">
                                            Device Name
                                        </label>
                                        <input
                                            type="text"
                                            placeholder="e.g. Living Room AC"
                                            value={newName}
                                            onChange={(e) => setNewName(e.target.value)}
                                            className="glass-input"
                                        />
                                    </div>
                                    <div>
                                        <label className="text-label-caps text-on-surface-variant uppercase tracking-widest mb-2 block">
                                            Power Limit (Watts)
                                        </label>
                                        <input
                                            type="number"
                                            value={newLimit}
                                            onChange={(e) => setNewLimit(e.target.value)}
                                            className="glass-input"
                                        />
                                    </div>
                                    <div>
                                        <label className="text-label-caps text-on-surface-variant uppercase tracking-widest mb-2 block">
                                            Auto-off (minutes)
                                        </label>
                                        <input
                                            type="number"
                                            placeholder="Default: 5"
                                            value={newAutoOff}
                                            onChange={(e) => setNewAutoOff(e.target.value)}
                                            className="glass-input"
                                        />
                                    </div>
                                </div>
                                <button
                                    onClick={handleAddDevice}
                                    className="btn-primary mt-5"
                                >
                                    Create Device
                                </button>
                            </div>
                        )}

                        {/* JUST CREATED - hardware setup panel */}
                        {justCreated && (
                            <div className="glass-card p-card-padding mb-8 border-electric-blue/30 relative overflow-hidden">
                                <div className="absolute inset-0 bg-gradient-to-r from-electric-blue/5 to-vibrant-violet/5" />
                                <div className="relative z-10">
                                    <div className="flex justify-between items-start">
                                        <h2 className="text-title-md text-electric-blue mb-2 flex items-center gap-2">
                                            <span className="material-symbols-outlined">check_circle</span>
                                            "{justCreated.name}" created — connect your sensor
                                        </h2>
                                        <button onClick={() => setJustCreated(null)} className="text-on-surface-variant hover:text-on-surface transition-colors">
                                            <span className="material-symbols-outlined text-[20px]">close</span>
                                        </button>
                                    </div>
                                    <p className="text-on-surface-variant text-body-md mb-4">
                                        Send readings from your ESP32/Arduino to this endpoint, with this device's API key in the header:
                                    </p>
                                    <div className="bg-surface-container-lowest rounded-xl p-4 font-mono text-data-mono space-y-2 overflow-x-auto border border-glass-stroke">
                                        <div className="text-electric-blue">POST {apiBase}/ingest</div>
                                        <div className="text-on-surface-variant">Header: <span className="text-vibrant-violet">x-api-key:</span> {justCreated.apiKey}</div>
                                        <div className="text-on-surface-variant">Body (JSON): <span className="text-on-surface">{'{ "power": 742 }'}</span></div>
                                    </div>
                                    <button
                                        onClick={() => copyToClipboard(justCreated.apiKey)}
                                        className="mt-4 btn-ghost flex items-center gap-2 text-sm"
                                    >
                                        <span className="material-symbols-outlined text-[16px]">content_copy</span>
                                        Copy API Key
                                    </button>
                                </div>
                            </div>
                        )}

                        {/* DEVICE LIST */}
                        {loading ? (
                            <div className="flex items-center justify-center py-20">
                                <div className="w-10 h-10 rounded-full border-2 border-vibrant-violet border-t-transparent animate-spin" />
                            </div>
                        ) : devices.length === 0 ? (
                            <div className="glass-card p-10 text-center">
                                <div className="w-16 h-16 rounded-full border border-glass-stroke flex items-center justify-center text-on-surface-variant mx-auto mb-4">
                                    <span className="material-symbols-outlined text-[32px]">devices</span>
                                </div>
                                <p className="text-on-surface-variant text-body-md">
                                    No devices yet. Click "Add Device" to register your first sensor.
                                </p>
                            </div>
                        ) : (
                            <div className="space-y-4">
                                {devices.map((device) => (
                                    <div
                                        key={device._id}
                                        className="glass-card-hover p-card-padding group"
                                    >
                                        {editing === device._id ? (
                                            /* EDIT MODE */
                                            <div className="grid grid-cols-1 md:grid-cols-4 gap-4 items-end">
                                                <div>
                                                    <label className="text-label-caps text-on-surface-variant uppercase tracking-widest mb-2 block">Name</label>
                                                    <input
                                                        value={editValues.name}
                                                        onChange={(e) => setEditValues({ ...editValues, name: e.target.value })}
                                                        className="glass-input py-3"
                                                    />
                                                </div>
                                                <div>
                                                    <label className="text-label-caps text-on-surface-variant uppercase tracking-widest mb-2 block">Power Limit (W)</label>
                                                    <input
                                                        type="number"
                                                        value={editValues.powerLimit}
                                                        onChange={(e) => setEditValues({ ...editValues, powerLimit: e.target.value })}
                                                        className="glass-input py-3"
                                                    />
                                                </div>
                                                <div>
                                                    <label className="text-label-caps text-on-surface-variant uppercase tracking-widest mb-2 block">Auto-off (min)</label>
                                                    <input
                                                        type="number"
                                                        value={editValues.autoOffMinutes}
                                                        onChange={(e) => setEditValues({ ...editValues, autoOffMinutes: e.target.value })}
                                                        className="glass-input py-3"
                                                    />
                                                </div>
                                                <div className="flex gap-2">
                                                    <button
                                                        onClick={() => saveEdit(device._id)}
                                                        className="btn-primary py-3 text-sm"
                                                    >
                                                        Save
                                                    </button>
                                                    <button
                                                        onClick={() => setEditing(null)}
                                                        className="btn-ghost py-3 text-sm"
                                                    >
                                                        Cancel
                                                    </button>
                                                </div>
                                            </div>
                                        ) : (
                                            /* VIEW MODE */
                                            <div className="flex flex-wrap justify-between items-center gap-4">
                                                <div>
                                                    <div className="flex items-center gap-3">
                                                        {/* Device icon */}
                                                        <div className={`
                                                            w-10 h-10 rounded-full flex items-center justify-center border transition-shadow
                                                            ${device.status === 'ON'
                                                                ? 'bg-vibrant-violet/20 text-vibrant-violet border-vibrant-violet/30 group-hover:shadow-[0_0_15px_rgba(139,92,246,0.4)]'
                                                                : 'bg-surface-container text-on-surface-variant border-glass-stroke'}
                                                        `}>
                                                            <span className="material-symbols-outlined text-[20px]">
                                                                {device.status === 'ON' ? 'power' : 'power_off'}
                                                            </span>
                                                        </div>

                                                        <h3 className="text-title-md font-inter text-on-surface">{device.name}</h3>

                                                        <span className={`
                                                            px-3 py-1 rounded-full text-label-caps uppercase tracking-widest flex items-center gap-1.5
                                                            ${device.status === 'ON'
                                                                ? 'bg-electric-blue/10 text-electric-blue border border-electric-blue/20'
                                                                : 'bg-surface-container text-on-surface-variant border border-glass-stroke'}
                                                        `}>
                                                            <span className={`w-1.5 h-1.5 rounded-full ${device.status === 'ON' ? 'bg-electric-blue animate-pulse' : 'bg-on-surface-variant/50'}`} />
                                                            {device.status}
                                                        </span>
                                                    </div>

                                                    <p className="text-on-surface-variant text-[13px] mt-2 ml-[52px] font-mono">
                                                        Limit: {device.powerLimit}W &nbsp;•&nbsp;
                                                        Auto-off: {device.autoOffMinutes || 'default'} min &nbsp;•&nbsp;
                                                        Last seen: {device.lastSeen ? new Date(device.lastSeen).toLocaleString() : 'never'}
                                                    </p>

                                                    {/* API Key Section */}
                                                    <div className="mt-3 ml-[52px] flex items-center gap-2">
                                                        {revealedKeys[device._id] ? (
                                                            <code className="bg-surface-container-lowest px-3 py-1.5 rounded-lg text-data-mono font-mono border border-glass-stroke text-on-surface-variant">
                                                                {device.apiKey}
                                                            </code>
                                                        ) : (
                                                            <button
                                                                onClick={() => setRevealedKeys({ ...revealedKeys, [device._id]: true })}
                                                                className="text-vibrant-violet text-[13px] hover:underline flex items-center gap-1"
                                                            >
                                                                <span className="material-symbols-outlined text-[14px]">key</span>
                                                                Show API key
                                                            </button>
                                                        )}
                                                        {revealedKeys[device._id] && (
                                                            <>
                                                                <button
                                                                    onClick={() => copyToClipboard(device.apiKey)}
                                                                    className="text-on-surface-variant text-[13px] hover:text-on-surface flex items-center gap-1 transition-colors"
                                                                >
                                                                    <span className="material-symbols-outlined text-[14px]">content_copy</span>
                                                                    Copy
                                                                </button>
                                                                <button
                                                                    onClick={() => regenerateKey(device)}
                                                                    className="text-error-red text-[13px] hover:underline flex items-center gap-1"
                                                                >
                                                                    <span className="material-symbols-outlined text-[14px]">autorenew</span>
                                                                    Regenerate
                                                                </button>
                                                            </>
                                                        )}
                                                    </div>
                                                </div>

                                                {/* Action buttons */}
                                                <div className="flex gap-2">
                                                    <button
                                                        disabled={busyId === device._id}
                                                        onClick={() => toggleDevice(device)}
                                                        className={`
                                                            px-4 py-2.5 rounded-xl text-label-caps uppercase tracking-widest font-semibold transition-all flex items-center gap-1.5
                                                            ${device.status === 'ON'
                                                                ? 'bg-error/10 text-error-red hover:bg-error/20 border border-error/20'
                                                                : 'bg-electric-blue/10 text-electric-blue hover:bg-electric-blue/20 border border-electric-blue/20'}
                                                        `}
                                                    >
                                                        <span className="material-symbols-outlined text-[16px]">power_settings_new</span>
                                                        {device.status === 'ON' ? 'Turn OFF' : 'Turn ON'}
                                                    </button>
                                                    <button
                                                        onClick={() => startEdit(device)}
                                                        className="btn-ghost py-2.5 px-4 text-label-caps uppercase tracking-widest flex items-center gap-1.5"
                                                    >
                                                        <span className="material-symbols-outlined text-[16px]">edit</span>
                                                        Edit
                                                    </button>
                                                    <button
                                                        onClick={() => deleteDevice(device)}
                                                        className="btn-ghost py-2.5 px-4 text-label-caps uppercase tracking-widest hover:bg-error/10 hover:text-error-red hover:border-error/20 flex items-center gap-1.5 transition-colors"
                                                    >
                                                        <span className="material-symbols-outlined text-[16px]">delete</span>
                                                        Delete
                                                    </button>
                                                </div>
                                            </div>
                                        )}
                                    </div>
                                ))}
                            </div>
                        )}

                    </div>
                </main>
            </div>
        </div>
    );
}

export default Devices;
